import itertools

def get_sts(n):
    # A Steiner Triple System exists if n = 1 or 3 mod 6.
    # For n=7, the STS(7) is unique up to isomorphism.
    if n == 7:
        return [(0, 1, 3), (1, 2, 4), (2, 3, 5), (3, 4, 6), (4, 5, 0), (5, 6, 1), (6, 0, 2)]
    return None

def count_monochromatic(triangles, coloring):
    count = 0
    for t in triangles:
        if coloring[t[0]] == coloring[t[1]] == coloring[t[2]]:
            count += 1
    return count

def solve():
    n = 7
    triangles = get_sts(n)
    min_monochromatic = float('inf')
    # Try all possible colorings (2^7 = 128)
    for coloring in itertools.product([0, 1], repeat=n):
        count = count_monochromatic(triangles, coloring)
        if count < min_monochromatic:
            min_monochromatic = count
    print(f"n=7, min monochromatic triangles: {min_monochromatic}")

solve()

