import itertools

def solve():
    n = 6
    all_triples = list(itertools.combinations(range(n), 3))
    # We want a subset of b=10 triples such that every pair is in exactly 2.
    # There are 20C10 = 184,756 subsets.
    # This is small enough to iterate.
    for subset in itertools.combinations(all_triples, 10):
        pairs = {}
        for triple in subset:
            for i in range(3):
                for j in range(i + 1, 3):
                    pair = tuple(sorted((triple[i], triple[j])))
                    pairs[pair] = pairs.get(pair, 0) + 1

        if all(count == 2 for count in pairs.values()):
            # Now check all colorings
            for coloring in itertools.product([0, 1], repeat=n):
                mono_count = 0
                for triple in subset:
                    if coloring[triple[0]] == coloring[triple[1]] == coloring[triple[2]]:
                        mono_count += 1
                if mono_count < 2:
                    return (subset, coloring, mono_count)
    return None

